def tests(b):
    j=json.loads(subprocess.check_output(['xcrun','xcresulttool','get','test-results','tests','--path',b]))
    out=[]
    def w(n):
        if n.get('nodeType')=='Test Case': out.append((n['nodeIdentifier'],n['name']))
