spans=[];idle=[];terms=[]
for b in ['suite.xcresult','signin.xcresult']:
    for ident,name in tests(b):
        acts=json.loads(subprocess.check_output(['xcrun','xcresulttool','get','test-results','activities','--path',b,'--test-id',ident]))['testRuns'][0]['activities']
        for i,a in enumerate(acts[:-1]):
            nx=acts[i+1]
