                # first UI query after launch: if it is an existence check that immediately succeeds
                if nx['title'].startswith(('Checking','Find','Waiting','Tap','Swipe','Get','Press')):
                    spans.append((nx['startTime']-a['startTime'],name,nx['title'][:50]))
                ch=a.get('childActivities',[{}])[0].get('childActivities',[])
                for c in ch:
                    if 'idle' in c['title']: idle.append(c['startTime']-a['startTime'])
            if a['title'].startswith('Terminate'):
                terms.append(nx['startTime']-a['startTime'])
